const inputItems = $input.all();
const normalizedItems = $('Classify Image Input Mode').all();
const outputItems = [];

const passthroughKeys = [
  'taskIndex', 'sceneIndex', 'sceneKey', 'sceneTitle', 'title', 'titleDescription',
  'taskDir', 'promptFileName', 'promptFilePath', 'productDetailFileName',
  'productDetailFilePath', 'rootOutputDir', 'productName', 'productDescription',
  'productAppearance', 'targetPlatform', 'targetMarket', 'ratio', 'timestamp',
  'workflowId', 'batchIndex', 'generationConcurrency', 'originalIndex', 'imageInputMode'
];

function text(value) {
  return value === undefined || value === null ? '' : String(value);
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(text(value).trim());
}

for (let itemIndex = 0; itemIndex < inputItems.length; itemIndex++) {
  const item = inputItems[itemIndex];
  const binary = item.binary || {};
  const source = normalizedItems[itemIndex]?.json || {};
  const prompt = text(source.prompt).trim();
  const negativePrompt = text(source.negativePrompt).trim();

  if (!prompt) {
    throw new Error(
      'Prepare Jimeng Image Input: missing prompt for itemIndex=' + itemIndex +
      ', taskIndex=' + text(source.taskIndex) +
      ', sceneKey=' + text(source.sceneKey) +
      ', originalIndex=' + text(source.originalIndex)
    );
  }

  const images = [];
  const images_base64 = [];
  const image_meta = [];

  if (source.imageInputMode === 'url') {
    for (let i = 1; i <= 5; i++) {
      const key = 'image-' + i;
      const url = text(source[key]).trim();
      if (!url) continue;
      if (!isHttpUrl(url)) throw new Error('Invalid HTTP image URL in ' + key + ' for itemIndex=' + itemIndex);
      images.push(url);
      image_meta.push({ key: 'image_' + i, source: 'siliconflow-url', url });
    }
  } else {
    for (let i = 1; i <= 5; i++) {
      const key = 'image_' + i;
      const bin = binary[key];
      if (!bin) continue;

      const mimeType = bin.mimeType || 'image/png';
      let buffer;
      try {
        buffer = await this.helpers.getBinaryDataBuffer(itemIndex, key);
      } catch (error) {
        if (bin.data && typeof bin.data === 'string') {
          const rawBase64 = bin.data.replace(/^data:[^;]+;base64,/, '');
          buffer = Buffer.from(rawBase64, 'base64');
        } else {
          throw new Error('Cannot read binary field ' + key + ': ' + error.message);
        }
      }

      const base64 = buffer.toString('base64');
      images.push('data:' + mimeType + ';base64,' + base64);
      images_base64.push(base64);
      image_meta.push({
        key,
        source: 'local-base64',
        mimeType,
        fileName: bin.fileName || (key + '.' + (bin.fileExtension || 'png')),
        fileExtension: bin.fileExtension || '',
        fileSize: buffer.length,
      });
    }
  }

  if (!images.length) {
    throw new Error(
      'No images were prepared for itemIndex=' + itemIndex +
      ', taskIndex=' + text(source.taskIndex) +
      ', sceneKey=' + text(source.sceneKey) +
      ', imageInputMode=' + text(source.imageInputMode)
    );
  }

  const passthrough = {};
  for (const key of passthroughKeys) {
    if (source[key] !== undefined) passthrough[key] = source[key];
  }

  outputItems.push({
    json: {
      ...passthrough,
      prompt,
      negativePrompt,
      model: source.model || 'jimeng-4.5',
      resolution: source.resolution || '2k',
      ratio: source.ratio || '1:1',
      images,
      images_base64,
      image_count: images.length,
      image_meta,
    },
    pairedItem: { item: itemIndex },
  });
}

return outputItems;

const inputItems = $input.all();
const plan = $('Build Retry Plan').first().json || {};
const finalResults = Array.isArray(plan.finalResults) ? plan.finalResults.slice() : [];
let retrySourceItems = [];
try {
  retrySourceItems = $('Expand Retry Items').all();
} catch (error) {
  retrySourceItems = [];
}

function extractUrls(body) {
  const imageUrls = [];
  const add = (value) => {
    if (!value) return;
    if (typeof value === 'string') {
      if (!value.startsWith('data:image/')) imageUrls.push(value);
    } else if (typeof value === 'object') {
      if (value.url) add(value.url);
      if (value.image_url) add(value.image_url);
      if (value.imageUrl) add(value.imageUrl);
      if (value.remoteUrl) add(value.remoteUrl);
      if (value.b64_json) imageUrls.push('data:image/png;base64,' + value.b64_json);
    }
  };
  const data = Array.isArray(body?.data) ? body.data : [];
  for (const row of data) add(row);
  if (Array.isArray(body?.urls)) for (const row of body.urls) add(row);
  if (Array.isArray(body?.images)) for (const row of body.images) add(row);
  return [...new Set(imageUrls.filter(Boolean))];
}

function sanitizeRaw(body) {
  if (!body || typeof body !== 'object') return body || {};
  const raw = { ...body };
  if (Array.isArray(raw.images)) raw.images = '[omitted ' + raw.images.length + ' input image(s)]';
  if (Array.isArray(raw.images_base64)) raw.images_base64 = '[omitted ' + raw.images_base64.length + ' raw Base64 image(s)]';
  return raw;
}

const metaKeys = [
  'taskIndex', 'sceneIndex', 'sceneKey', 'sceneTitle', 'title', 'titleDescription',
  'taskDir', 'promptFileName', 'promptFilePath', 'productDetailFileName',
  'productDetailFilePath', 'rootOutputDir', 'productName', 'productDescription',
  'productAppearance', 'targetPlatform', 'targetMarket', 'ratio', 'timestamp',
  'workflowId', 'batchIndex', 'generationConcurrency', 'originalIndex'
];

function buildMeta(source) {
  const meta = {};
  for (const key of metaKeys) {
    if (source[key] !== undefined) meta[key] = source[key];
  }
  return meta;
}

function readMessage(body) {
  return String(
    body?.message ||
    body?.errorMessage ||
    body?.error?.message ||
    body?.error?.errorMessage ||
    body?.cause?.message ||
    ''
  );
}

function buildRetryResult(body, retrySource) {
  const urls = extractUrls(body);
  const hasBusinessError = body?.code !== undefined && body.code !== 0;
  const success = !hasBusinessError && urls.length > 0;
  const previous = retrySource.firstRaw || {};
  const message = readMessage(body);
  return {
    ...buildMeta(retrySource),
    originalIndex: retrySource.originalIndex,
    success,
    ok: success,
    code: body?.code ?? (success ? 0 : previous.code ?? -1),
    message: message || (success ? '' : readMessage(previous) || 'Retry finished without image URLs'),
    count: urls.length,
    image_urls: urls,
    urls,
    retryAttempt: 1,
    retryReason: retrySource.retryReason || '',
    firstRaw: previous,
    raw: sanitizeRaw(body),
  };
}

for (let i = 0; i < inputItems.length; i++) {
  const retrySource = retrySourceItems[i]?.json;
  if (!retrySource || retrySource.originalIndex === undefined) continue;
  const retryBody = inputItems[i]?.json || {};
  finalResults[retrySource.originalIndex] = buildRetryResult(retryBody, retrySource);
}

return finalResults
  .map((result, index) => ({ result, index }))
  .filter((row) => row.result)
  .sort((a, b) => a.index - b.index)
  .map((row) => ({
    json: row.result,
    pairedItem: { item: row.index },
  }));

const root = $input.first()?.json || {};
const sourceItems = Array.isArray(root.batchItems) && root.batchItems.length ? root.batchItems : [root];
const hardLimit = 7;
const requestedLimit = Number(root.generationConcurrency ?? hardLimit);
const limit = Math.max(1, Math.min(sourceItems.length, hardLimit, Number.isFinite(requestedLimit) ? requestedLimit : hardLimit));

function pick(task, names, fallback = '') {
  for (const name of names) {
    const value = task?.[name];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return fallback;
}

const rootPrompt = pick(root, ['prompt', 'imagePrompt', 'mainPrompt'], '');
const rootNegativePrompt = pick(root, ['negativePrompt', 'negative_prompt', 'negative'], '');
const rootModel = pick(root, ['model'], 'jimeng-4.5');
const rootResolution = pick(root, ['resolution'], '2k');
const rootRatio = pick(root, ['ratio'], '1:1');

return sourceItems.slice(0, limit).map((task, index) => {
  const imageCount = Number(task.image_count ?? task.imageCount ?? task.viewImages?.length ?? 5);
  const incomingOriginalIndex = Number(task.originalIndex);
  const originalIndex = Number.isFinite(incomingOriginalIndex) ? incomingOriginalIndex : index;

  return {
    json: {
      ...task,
      originalIndex,
      'image-1': pick(task, ['image-1', 'viewImageAdd1']),
      'image-2': pick(task, ['image-2', 'viewImageAdd2']),
      'image-3': pick(task, ['image-3', 'viewImageAdd3']),
      'image-4': pick(task, ['image-4', 'viewImageAdd4']),
      'image-5': pick(task, ['image-5', 'viewImageAdd5']),
      prompt: pick(task, ['prompt', 'imagePrompt', 'mainPrompt', 'scenePrompt'], rootPrompt),
      negativePrompt: pick(task, ['negativePrompt', 'negative_prompt', 'negative'], rootNegativePrompt),
      model: pick(task, ['model'], rootModel),
      resolution: pick(task, ['resolution'], rootResolution),
      ratio: pick(task, ['ratio'], rootRatio),
      image_count: Number.isFinite(imageCount) ? imageCount : 5,
      batchIndex: index,
      generationConcurrency: limit,
    },
    pairedItem: { item: 0 },
  };
});

const items = $input.all();
const sourceItems = $('Generate Base64 Image').all();

function extractUrls(body) {
  const imageUrls = [];
  const add = (value) => {
    if (!value) return;
    if (typeof value === 'string') {
      if (!value.startsWith('data:image/')) imageUrls.push(value);
    } else if (typeof value === 'object') {
      if (value.url) add(value.url);
      if (value.image_url) add(value.image_url);
      if (value.imageUrl) add(value.imageUrl);
      if (value.remoteUrl) add(value.remoteUrl);
      if (value.b64_json) imageUrls.push('data:image/png;base64,' + value.b64_json);
    }
  };
  const data = Array.isArray(body?.data) ? body.data : [];
  for (const row of data) add(row);
  if (Array.isArray(body?.urls)) for (const row of body.urls) add(row);
  if (Array.isArray(body?.images)) for (const row of body.images) add(row);
  return [...new Set(imageUrls.filter(Boolean))];
}

function sanitizeRaw(body) {
  if (!body || typeof body !== 'object') return body || {};
  const raw = { ...body };
  if (Array.isArray(raw.images)) raw.images = '[omitted ' + raw.images.length + ' input image(s)]';
  if (Array.isArray(raw.images_base64)) raw.images_base64 = '[omitted ' + raw.images_base64.length + ' raw Base64 image(s)]';
  return raw;
}

const metaKeys = [
  'taskIndex', 'sceneIndex', 'sceneKey', 'sceneTitle', 'title', 'titleDescription',
  'taskDir', 'promptFileName', 'promptFilePath', 'productDetailFileName',
  'productDetailFilePath', 'rootOutputDir', 'productName', 'productDescription',
  'productAppearance', 'targetPlatform', 'targetMarket', 'ratio', 'timestamp',
  'workflowId', 'batchIndex', 'generationConcurrency', 'originalIndex'
];
const finalResults = [];
const retryItems = [];

function buildMeta(source) {
  const meta = {};
  for (const key of metaKeys) {
    if (source[key] !== undefined) meta[key] = source[key];
  }
  return meta;
}

function readMessage(body) {
  return String(
    body?.message ||
    body?.errorMessage ||
    body?.error?.message ||
    body?.error?.errorMessage ||
    body?.cause?.message ||
    ''
  );
}

function buildResult(body, source, fallbackIndex, retryInfo) {
  const urls = extractUrls(body);
  const originalIndex = Number.isFinite(Number(source.originalIndex)) ? Number(source.originalIndex) : fallbackIndex;
  const hasBusinessError = body?.code !== undefined && body.code !== 0;
  const success = !hasBusinessError && urls.length > 0;
  const message = readMessage(body);
  return {
    ...buildMeta(source),
    originalIndex,
    success,
    ok: success,
    code: body?.code ?? (success ? 0 : -1),
    message: message || (success ? '' : 'Generation finished without image URLs'),
    count: urls.length,
    image_urls: urls,
    urls,
    retryAttempt: retryInfo?.retryAttempt || 0,
    retryReason: retryInfo?.retryReason || '',
    raw: sanitizeRaw(body),
  };
}

function getRetryReason(body, urls) {
  const message = readMessage(body);
  if (body?.code !== undefined && body.code !== 0) return 'business_error_code_' + body.code;
  if (body?.data === null) return 'empty_data';
  if (/upload|上传|bad gateway|gateway|timeout|timed out|ECONN|fetch failed|socket|network|ETIMEDOUT|ECONNRESET|ECONNREFUSED/i.test(message)) return 'request_failed';
  if (!urls.length) return 'empty_image_urls';
  return '';
}

for (let index = 0; index < items.length; index++) {
  const body = items[index]?.json || {};
  const source = sourceItems[index]?.json || {};
  const originalIndex = Number.isFinite(Number(source.originalIndex)) ? Number(source.originalIndex) : index;
  const urls = extractUrls(body);
  const reason = getRetryReason(body, urls);

  if (reason) {
    finalResults[originalIndex] = buildResult(body, source, originalIndex, { retryAttempt: 0, retryReason: reason });
    retryItems.push({
      ...source,
      originalIndex,
      retryAttempt: 1,
      retryReason: reason,
      firstRaw: sanitizeRaw(body),
    });
  } else {
    finalResults[originalIndex] = buildResult(body, source, originalIndex);
  }
}

return [{
  json: {
    totalCount: items.length,
    retryCount: retryItems.length,
    hasRetryItems: retryItems.length > 0,
    finalResults,
    retryItems,
  },
}];

const root = $input.first()?.json || {};
const retryItems = Array.isArray(root.retryItems) ? root.retryItems : [];
return retryItems.map((item, index) => ({
  json: item,
  pairedItem: { item: index },
}));

const items = $input.all();

function cleanString(value) {
  return String(value ?? '').trim();
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(cleanString(value));
}

const classified = items.map((item, index) => {
  const json = item.json || {};
  const values = [];
  for (let imageIndex = 1; imageIndex <= 5; imageIndex++) {
    const value = cleanString(json['image-' + imageIndex]);
    if (value) values.push(value);
  }
  if (!values.length) {
    throw new Error('No image inputs found for item ' + (index + 1));
  }
  const urlCount = values.filter(isHttpUrl).length;
  if (urlCount > 0 && urlCount !== values.length) {
    throw new Error('Mixed local paths and HTTP image URLs are not supported within one task at item ' + (index + 1));
  }
  return {
    json: {
      ...json,
      imageInputMode: urlCount === values.length ? 'url' : 'file',
    },
    pairedItem: item.pairedItem || { item: index },
  };
});

const modes = [...new Set(classified.map((item) => item.json.imageInputMode))];
if (modes.length !== 1) {
  throw new Error('A single S003 batch cannot mix URL-mode tasks and local-file tasks.');
}

return classified;
